import sys, os, time, json, re, subprocess, shutil; sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from zkl import *
tee('z77'); R = {}
D = ZDATA / 'sasl'; shutil.rmtree(D, ignore_errors=True); D.mkdir(parents=True)
def one(o, n=3): return ' | '.join(l.strip() for l in (o or '(无输出)').splitlines()[:n])[:200]
(D / 'server-digest.conf').write_text('Server {\n  org.apache.zookeeper.server.auth.DigestLoginModule required\n  user_bob="bobsecret"\n  user_alice="alicesecret";\n};\n')
(D / 'client-bob.conf').write_text('Client {\n  org.apache.zookeeper.server.auth.DigestLoginModule required\n  username="bob" password="bobsecret";\n};\n')
(D / 'client-badpw.conf').write_text('Client {\n  org.apache.zookeeper.server.auth.DigestLoginModule required\n  username="bob" password="WRONG";\n};\n')
cj = lambda f: [f'-Djava.security.auth.login.config={D / f}', '-Dzookeeper.fips-mode=false']
print('  (ZooKeeper 3.9 默认 zookeeper.fips-mode=true,日志「Client will not use DIGEST-MD5 as SASL mechanism, because FIPS mode is enabled.」,要用 DIGEST-MD5 必须在客户端和服务端都关掉它)')
print('== 一:SASL DIGEST-MD5(不需要 KDC):服务端 JAAS 里定义用户 bob / alice,zoo.cfg 里 authProvider.1=SASLAuthenticationProvider')
n = Node('z77', 7300, conf={'authProvider.1': 'org.apache.zookeeper.server.auth.SASLAuthenticationProvider'}, jvm=cj('server-digest.conf')).start()
R['anon'] = one(cli(7300, 'whoami')[0]); print('  不带 JAAS 的客户端 whoami →', R['anon'])
R['bob'] = one(cli(7300, 'whoami', jvm=cj('client-bob.conf'))[0], 5); print('  JAAS 里是 bob 的客户端 whoami →', R['bob'])
o = cli(7300, 'whoami', jvm=cj('client-badpw.conf'), timeout=40)[0]; R['badpw'] = one(o); print('  口令错误的客户端 whoami →', R['badpw'])
print()
print('== 二:sasl ACL:bob 创建只允许 sasl:bob 访问的节点,alice 与匿名去读')
R['create'] = one(cli(7300, 'create /bobs data sasl:bob:cdrwa', jvm=cj('client-bob.conf'))[0]); print('  bob 创建 /bobs →', R['create'])
(D / 'client-alice.conf').write_text('Client {\n  org.apache.zookeeper.server.auth.DigestLoginModule required\n  username="alice" password="alicesecret";\n};\n')
R['bob_get'] = one(cli(7300, 'get /bobs', jvm=cj('client-bob.conf'))[0]); R['alice_get'] = one(cli(7300, 'get /bobs', jvm=cj('client-alice.conf'))[0]); R['anon_get'] = one(cli(7300, 'get /bobs')[0])
print('  bob 读 →', R['bob_get']); print('  alice 读 →', R['alice_get']); print('  匿名读 →', R['anon_get'])
n.stop()
print()
print('== 三:-Dzookeeper.enforce.auth.enabled=true -Dzookeeper.enforce.auth.schemes=sasl:强制必须先 SASL 认证才能做任何事(我先试过 requireClientAuthScheme,没有效果)')
m = Node('z77b', 7301, conf={'authProvider.1': 'org.apache.zookeeper.server.auth.SASLAuthenticationProvider'}, jvm=cj('server-digest.conf') + ['-Dzookeeper.enforce.auth.enabled=true', '-Dzookeeper.enforce.auth.schemes=sasl']).start()
R['req_anon'] = one(cli(7301, 'ls /')[0]); R['req_bob'] = one(cli(7301, 'ls /', jvm=cj('client-bob.conf'))[0]); print('  匿名 ls / →', R['req_anon']); print('  bob ls / →', R['req_bob'])
m.stop()
print()
print('== 四:Kerberos(GSSAPI):本机用 brew 的 krb5 起一个 KDC(realm ZK.TEST,端口 7650,只在本机),服务主体 zookeeper/localhost、客户端主体 zkclient,都用 keytab 登录(不碰你的票据缓存)')
K = ZDATA / 'krb'; shutil.rmtree(K, ignore_errors=True); (K / 'kdc').mkdir(parents=True)
(K / 'krb5.conf').write_text('[libdefaults]\n default_realm = ZK.TEST\n dns_lookup_kdc = false\n dns_lookup_realm = false\n rdns = false\n udp_preference_limit = 1\n[realms]\n ZK.TEST = {\n  kdc = 127.0.0.1:7650\n }\n[domain_realm]\n localhost = ZK.TEST\n')
(K / 'kdc.conf').write_text(f'[kdcdefaults]\n kdc_ports = 7650\n kdc_tcp_ports = 7650\n[realms]\n ZK.TEST = {{\n  database_name = {K}/kdc/principal\n  key_stash_file = {K}/kdc/.k5.ZK.TEST\n  max_life = 1h\n  master_key_type = aes256-cts\n  supported_enctypes = aes256-cts:normal aes128-cts:normal\n }}\n')
env = dict(os.environ, KRB5_CONFIG=str(K / 'krb5.conf'), KRB5_KDC_PROFILE=str(K / 'kdc.conf')); B = '/opt/homebrew/opt/krb5'
def kr(*a): return subprocess.run(a, env=env, capture_output=True, text=True, cwd=K)
kr(f'{B}/sbin/kdb5_util', '-r', 'ZK.TEST', 'create', '-s', '-P', 'masterpw')
for p, kt in (('zookeeper/localhost@ZK.TEST', 'zk.keytab'), ('zkclient@ZK.TEST', 'client.keytab'), ('otheruser@ZK.TEST', 'other.keytab')):
    kr(f'{B}/sbin/kadmin.local', '-q', f'addprinc -randkey {p}'); kr(f'{B}/sbin/kadmin.local', '-q', f'ktadd -k {K}/{kt} {p}')
kdc = subprocess.Popen([f'{B}/sbin/krb5kdc', '-n'], env=env, stdout=open(K / 'kdc.log', 'w'), stderr=subprocess.STDOUT); time.sleep(2)
(K / 'server.conf').write_text(f'Server {{\n  com.sun.security.auth.module.Krb5LoginModule required useKeyTab=true keyTab="{K}/zk.keytab" storeKey=true useTicketCache=false principal="zookeeper/localhost@ZK.TEST";\n}};\n')
for nm, kt, pr in (('client-krb', 'client.keytab', 'zkclient@ZK.TEST'), ('client-other', 'other.keytab', 'otheruser@ZK.TEST')):
    (K / f'{nm}.conf').write_text(f'Client {{\n  com.sun.security.auth.module.Krb5LoginModule required useKeyTab=true keyTab="{K}/{kt}" storeKey=true useTicketCache=false principal="{pr}";\n}};\n')
kj = lambda f: [f'-Djava.security.auth.login.config={K / f}', f'-Djava.security.krb5.conf={K / "krb5.conf"}']
k = Node('z77k', 7302, conf={'authProvider.1': 'org.apache.zookeeper.server.auth.SASLAuthenticationProvider'}, jvm=kj('server.conf')).start()
R['krb_whoami'] = one(cli(7302, 'whoami', jvm=kj('client-krb.conf'), timeout=60)[0], 5); print('  zkclient(Kerberos 登录)whoami →', R['krb_whoami'])
R['krb_create'] = one(cli(7302, 'create /krbnode data sasl:zkclient@ZK.TEST:cdrwa', jvm=kj('client-krb.conf'), timeout=60)[0]); print('  zkclient 创建 /krbnode(ACL = sasl:zkclient@ZK.TEST)→', R['krb_create'])
R['krb_other'] = one(cli(7302, 'get /krbnode', jvm=kj('client-other.conf'), timeout=60)[0]); print('  otheruser(也是合法的 Kerberos 用户)读 →', R['krb_other'])
R['krb_anon'] = one(cli(7302, 'get /krbnode', timeout=60)[0]); print('  没有凭据的客户端读 →', R['krb_anon'])
k.stop(); kdc.terminate()
save('z77', R)
